//! 🧪️ Actual native reserved routing receives the original arguments, checkpoints the real parent and closes each cancelled source prefix.
use super::*;
use semio_framework_plugin_job::reserved_jobs::original_checkpoint::OriginalCheckpointRoute as Route;
use store::NoMembers;
#[test]fn original_checkpoint_route_receives_native_arguments_and_preserves_actual_parent_command(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for cut in law["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut caller,&mut decoder);let g=RetainedCloneGrant{maximum_copy_bytes:4096,maximum_capacity_bytes:16<<20,..TURN};let report=semio_framework_os_store_engine_replay::prepare_report(&mut store,&mut caller,&mut decoder);crate::original_stream_abort::close_report_fixture(report,&mut caller,&mut decoder);let message=law["message"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize);let author=&law["authors"][0];let mut args=Some(semio_framework_value::DslValue::Object(vec![("message".into(),semio_framework_value::DslValue::String(message.clone())),("authors".into(),semio_framework_value::DslValue::Array(vec![semio_framework_value::DslValue::Object(vec![("id".into(),semio_framework_value::DslValue::String(author["id"].as_str().unwrap().into())),("name".into(),semio_framework_value::DslValue::String(author["name"].as_str().unwrap().into())),("avatar".into(),semio_framework_value::DslValue::String(author["avatar"].as_str().unwrap().into()))])]))]));let pointer=args.as_ref().unwrap().get("message").unwrap().as_str().unwrap().as_ptr();let roster=(0,0,0);let mut route=None;let d=Route::capture_demands();for axis in [0,1,2,4]{let mut denied=g;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>denied.maximum_depth=0};turn(&mut caller,&mut decoder,denied,|cx|{assert!(!Route::admit(&mut args,roster,cx,&mut route)?);Ok(())});assert_eq!(args.as_ref().unwrap().get("message").unwrap().as_str().unwrap().as_ptr(),pointer);assert!(route.is_none());}turn(&mut caller,&mut decoder,g,|cx|{assert!(Route::admit(&mut args,roster,cx,&mut route)?);Ok(())});assert!(args.is_none());for index in 0..262144{if cut==Some(index)||route.as_ref().unwrap().ready(){break}let mut admitted=g;if let Some(d)=route.as_ref().unwrap().next_construction_demands::<NoMembers,_>(None,&*store){admitted.maximum_copy_bytes=admitted.maximum_copy_bytes.max(d.copy_bytes);admitted.maximum_capacity_bytes=admitted.maximum_capacity_bytes.max(d.capacity_bytes);admitted.maximum_depth=admitted.maximum_depth.max(d.depth);}turn(&mut caller,&mut decoder,admitted,|cx|route.as_mut().unwrap().advance::<NoMembers,_>(roster,None,&mut *store,cx));assert!(index<262143,"native reserved checkpoint source stalled");}if cut.is_none(){let mut output=None;turn(&mut caller,&mut decoder,g,|cx|{assert!(route.as_mut().unwrap().take(roster,cx,&mut output)?);Ok(())});let(changed,pins)=output.unwrap();assert_eq!(changed,law["expected"]["changed"].as_bool().unwrap());assert_eq!(pins.len(),law["expected"]["pins"].as_u64().unwrap()as usize);let actual=store.parts_ref().log.envelope.vcs.checkpoints.get(0).unwrap();assert_eq!(actual.message.as_deref(),Some(message.as_str()));assert_eq!(actual.authors.len(),1);assert_eq!(actual.authors[0].id,author["id"]);assert_eq!(actual.authors[0].name,author["name"]);assert_eq!(actual.authors[0].avatar.as_deref(),author["avatar"].as_str());close_typed(pins,&mut caller,&mut decoder);}else{caller.cancel().cancel_now();}
 for index in 0..262144{if route.as_ref().unwrap().terminal_is_empty(){break}let d=route.as_ref().unwrap().close_demands::<NoMembers,_>(None,&*store).unwrap();let selected=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.max(d.copy_bytes),maximum_capacity_bytes:g.maximum_capacity_bytes.max(d.capacity_bytes),maximum_release_bytes:g.maximum_release_bytes.max(d.release_bytes),maximum_depth:g.maximum_depth.max(d.depth),..g};turn(&mut caller,&mut decoder,selected,|cx|cx.with_original_retirement(|cx|route.as_mut().unwrap().close_step::<NoMembers,_>(roster,None,&mut *store,cx)));assert!(index<262143,"native reserved checkpoint closure stalled");}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=Route::release_demands();close_original_retained_step(cx,d,|_|{route.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut caller,&mut decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut caller,&mut decoder);while !decoder.terminal_is_empty(){caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(g);
 }
}
